#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <cstring>
#include <stdexcept>
#include <openssl/evp.h>
#include <openssl/rand.h>

namespace securedb {

struct UserContext {
    uint32_t user_id;
    uint32_t tenant_id;
    uint8_t role_flags;
};

struct EncryptedRecord {
    std::vector<uint8_t> ciphertext;
    std::vector<uint8_t> iv;
    std::vector<uint8_t> tag;
    uint32_t owner_tenant_id;
    uint32_t record_id;
};

class KeyDerivation {
public:
    static std::vector<uint8_t> derive_tenant_key(
        const std::vector<uint8_t>& master_key,
        uint32_t tenant_id
    ) {
        std::vector<uint8_t> derived(32);
        std::vector<uint8_t> salt(16);
        // Encode tenant_id into salt for domain separation
        memcpy(salt.data(), &tenant_id, sizeof(tenant_id));
        if (PKCS5_PBKDF2_HMAC(
                reinterpret_cast<const char*>(master_key.data()),
                master_key.size(),
                salt.data(), salt.size(),
                10000, EVP_sha256(),
                derived.size(), derived.data()) != 1) {
            throw std::runtime_error("key derivation failed");
        }
        return derived;
    }
};

class RecordCache {
    std::unordered_map<uint32_t, EncryptedRecord> cache_;
public:
    void store(uint32_t record_id, const EncryptedRecord& rec) {
        cache_[record_id] = rec;
    }

    EncryptedRecord* lookup(uint32_t record_id) {
        auto it = cache_.find(record_id);
        if (it != cache_.end()) return &it->second;
        return nullptr;
    }
};

class SecureDriver {
    std::vector<uint8_t> master_key_;
    RecordCache cache_;

    bool authorize_access(
        const UserContext& ctx,
        const EncryptedRecord& record
    ) {
        // Check tenant isolation
        if (ctx.tenant_id != record.owner_tenant_id) {
            return false;
        }
        return true;
    }

    std::vector<uint8_t> decrypt_record(
        const EncryptedRecord& record,
        uint32_t requesting_tenant_id
    ) {
        // Derive key based on requesting user's tenant
        auto key = KeyDerivation::derive_tenant_key(
            master_key_, requesting_tenant_id
        );

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (ctx == nullptr) {
            return {};
        }
        std::vector<uint8_t> plaintext(record.ciphertext.size());
        int len = 0;

        if (EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr,
                              key.data(), record.iv.data()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return {};
        }
        if (EVP_DecryptUpdate(ctx, plaintext.data(), &len,
                             record.ciphertext.data(),
                             record.ciphertext.size()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return {};
        }

        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, 16,
                               const_cast<uint8_t*>(record.tag.data())) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return {};
        }

        int ret = EVP_DecryptFinal_ex(ctx, plaintext.data() + len, &len);
        EVP_CIPHER_CTX_free(ctx);

        // If decryption fails (wrong key), return empty
        if (ret <= 0) {
            return {};
        }
        return plaintext;
    }

public:
    SecureDriver(const std::vector<uint8_t>& master_key)
        : master_key_(master_key) {}

    bool insert_record(
        const UserContext& ctx,
        uint32_t record_id,
        const std::vector<uint8_t>& data
    ) {
        auto key = KeyDerivation::derive_tenant_key(
            master_key_, ctx.tenant_id
        );

        EncryptedRecord rec;
        rec.owner_tenant_id = ctx.tenant_id;
        rec.record_id = record_id;
        rec.iv.resize(12);
        // Ensure a strong, unique nonce; abort on RNG failure to avoid
        // catastrophic AES-GCM nonce reuse.
        if (RAND_bytes(rec.iv.data(), 12) != 1) {
            return false;
        }
        rec.ciphertext.resize(data.size());
        rec.tag.resize(16);

        EVP_CIPHER_CTX* ectx = EVP_CIPHER_CTX_new();
        if (ectx == nullptr) {
            return false;
        }
        int len = 0;
        if (EVP_EncryptInit_ex(ectx, EVP_aes_256_gcm(), nullptr,
                              key.data(), rec.iv.data()) != 1) {
            EVP_CIPHER_CTX_free(ectx);
            return false;
        }
        if (EVP_EncryptUpdate(ectx, rec.ciphertext.data(), &len,
                             data.data(), data.size()) != 1) {
            EVP_CIPHER_CTX_free(ectx);
            return false;
        }
        if (EVP_EncryptFinal_ex(ectx, rec.ciphertext.data() + len, &len) != 1) {
            EVP_CIPHER_CTX_free(ectx);
            return false;
        }
        if (EVP_CIPHER_CTX_ctrl(ectx, EVP_CTRL_GCM_GET_TAG, 16,
                               rec.tag.data()) != 1) {
            EVP_CIPHER_CTX_free(ectx);
            return false;
        }
        EVP_CIPHER_CTX_free(ectx);

        cache_.store(record_id, rec);
        return true;
    }

    std::vector<uint8_t> read_record(
        const UserContext& ctx,
        uint32_t record_id
    ) {
        EncryptedRecord* rec = cache_.lookup(record_id);
        if (!rec) return {};

        if (!authorize_access(ctx, *rec)) {
            return {};
        }

        // Use the requesting user's tenant_id for decryption key derivation
        // This provides cryptographic enforcement of tenant isolation
        return decrypt_record(*rec, ctx.tenant_id);
    }

    bool update_record(
        const UserContext& ctx,
        uint32_t record_id,
        const std::vector<uint8_t>& new_data
    ) {
        EncryptedRecord* rec = cache_.lookup(record_id);
        if (!rec) return false;

        if (!authorize_access(ctx, *rec)) {
            return false;
        }

        // Re-encrypt with the caller's tenant key
        return insert_record(ctx, record_id, new_data);
    }

    // Batch operation: transfer records between tenants (admin only)
    bool transfer_record(
        const UserContext& admin_ctx,
        uint32_t record_id,
        uint32_t target_tenant_id
    ) {
        if (!(admin_ctx.role_flags & 0x80)) return false;

        EncryptedRecord* rec = cache_.lookup(record_id);
        if (!rec) return false;

        // Decrypt with original tenant key
        auto plaintext = decrypt_record(*rec, rec->owner_tenant_id);
        if (plaintext.empty()) return false;

        // Re-encrypt for target tenant
        UserContext target_ctx{0, target_tenant_id, 0};
        return insert_record(target_ctx, record_id, plaintext);
    }

    // Cross-tenant query for analytics (reads metadata only)
    std::vector<uint32_t> list_records_for_tenant(
        const UserContext& ctx,
        uint32_t query_tenant_id
    ) {
        // Authorization: users can only list their own tenant's records
        // unless they have analytics role flag
        if (ctx.tenant_id != query_tenant_id && 
            !(ctx.role_flags & 0x40)) {
            return {};
        }
        // Return record IDs (metadata only, no data access)
        return {}; // Simplified - would query backing store
    }
};

} // namespace securedb
